#!/usr/bin/env python3
"""Recompute the CSX-051_Q2 ground truth from local package files."""

from __future__ import annotations

import json
import re
from collections import Counter
from pathlib import Path


TASK_DIR = Path(__file__).resolve().parent
REPO_ROOT = TASK_DIR.parents[2]
PACKAGE_ROOT = REPO_ROOT / "event_packages" / "standard_event_packages" / "packages" / "CSX-051"

SOURCE_FILES = [
    "metadata/event.json",
    "data/event_reports/event_reports_002_Wikipedia_2021_Henan_floods.json",
    "data/event_reports/event_reports_003_Locked_event_anchor_July_2021_Henan_Zhengzhou_extreme_rainfall_and_flood.json",
    "data/physical_hazard/physical_hazard_002_ERA5-Land_hourly_aggregate_stats.json",
    "data/physical_hazard/physical_hazard_004_GPM_IMERG_V07_event_accumulated_precipitation.json",
    "data/physical_hazard/physical_hazard_006_CHIRPS_daily_event_accumulated_precipitation.json",
    "data/exposure_impact/exposure_impact_003_Overpass_small_roads_and_critical_amenities.json",
    "data/exposure_impact/exposure_impact_004_WorldPop_GP_100m_population_sum.json",
    "data/remote_sensing/remote_sensing_003_Google_Satellite_Embedding_annual_cosine-change_stats.json",
    "data/remote_sensing/remote_sensing_005_Sentinel-1_GRD_VV_pre_post_change.json",
]


def read_json(rel_path: str) -> dict:
    return json.loads((PACKAGE_ROOT / rel_path).read_text(encoding="utf-8", errors="replace"))


def rounded(value: float, digits: int = 3) -> float:
    return round(float(value), digits)


def extract_hourly_peak_mm(text: str) -> float:
    match = re.search(
        r"recorded\s+([0-9]+(?:\.[0-9]+)?)\s+millimetres.*?within an hour",
        text,
        flags=re.IGNORECASE,
    )
    if not match:
        raise ValueError("Could not extract the reported hourly rainfall peak.")
    return float(match.group(1))


def overpass_context() -> dict:
    data = read_json("data/exposure_impact/exposure_impact_003_Overpass_small_roads_and_critical_amenities.json")
    amenities: Counter[str] = Counter()
    road_ways = 0
    bridge_tagged = 0

    for element in data.get("elements", []):
        tags = element.get("tags") or {}
        if element.get("type") == "way" and tags.get("highway"):
            road_ways += 1
        if "bridge" in tags:
            bridge_tagged += 1
        amenity = tags.get("amenity")
        if amenity:
            amenities[amenity] += 1

    return {
        "road_ways": road_ways,
        "bridge_tagged": bridge_tagged,
        "critical_service_nodes": sum(
            amenities[name] for name in ("hospital", "school", "police", "fire_station", "shelter")
        ),
    }


def scoring_rubric() -> list[dict]:
    return [
        {
            "name": "JSON form and diagnosis",
            "points": 3,
            "description": (
                "Returns the requested JSON shape and gives the diagnosis label "
                "peak_hour_burst_embedded_in_wet_event_window or a clear equivalent."
            ),
            "partial_credit": "1 point for a valid compact JSON object; 1 point for the correct label family; 1 point for not substituting a surface-change or exposure-first answer.",
        },
        {
            "name": "Rainfall metrics and ratios",
            "points": 5,
            "description": (
                "Reports the 201.9 mm hourly peak, the three event-window means near "
                "426.100, 256.635, and 214.341 mm, and the three peak-share ratios "
                "near 0.474, 0.787, and 0.942."
            ),
            "partial_credit": "Up to 2 points for the peak and event means; up to 2 points for the three ratios; 1 point for rounding within the stated tolerance.",
        },
        {
            "name": "Product comparison",
            "points": 3,
            "description": (
                "Uses the all-products-above-200 mm check and the 1.988 spread ratio "
                "to show why the case is not isolated-hour-only and not capped by the "
                "lowest product."
            ),
            "partial_credit": "1 point for the above-200 mm check; 1 point for the spread ratio; 1 point for rejecting the two incorrect calibration shortcuts.",
        },
        {
            "name": "Surface-change role",
            "points": 3,
            "description": (
                "Treats rainfall timing and accumulation as the primary calibration, "
                "while using Sentinel-1 or AlphaEarth values only as surface-change context."
            ),
            "partial_credit": "1 point for naming the surface-change values; 1 point for using them only as context; 1 point for keeping rainfall as the controlling evidence.",
        },
        {
            "name": "Urban context metrics",
            "points": 3,
            "description": (
                "Gives at least three correct context metrics among population 11097000, "
                "road ways 252, bridge-tagged ways 108, and critical service nodes 48."
            ),
            "partial_credit": "1 point for each correct context metric, capped at 3 points.",
        },
        {
            "name": "Concise interpretation",
            "points": 3,
            "description": (
                "Keeps the interpretation concise and avoids invented casualty, outage, "
                "facility-failure, or flood-depth values."
            ),
            "partial_credit": "1 point for a concise final interpretation; 1 point for no invented impact numbers; 1 point for aligning the prose with the computed label.",
        },
    ]


def build_ground_truth() -> dict:
    event = read_json("metadata/event.json")
    locked = read_json(
        "data/event_reports/event_reports_003_Locked_event_anchor_July_2021_Henan_Zhengzhou_extreme_rainfall_and_flood.json"
    )
    wiki = read_json("data/event_reports/event_reports_002_Wikipedia_2021_Henan_floods.json")
    gpm = read_json("data/physical_hazard/physical_hazard_004_GPM_IMERG_V07_event_accumulated_precipitation.json")
    chirps = read_json("data/physical_hazard/physical_hazard_006_CHIRPS_daily_event_accumulated_precipitation.json")
    era5 = read_json("data/physical_hazard/physical_hazard_002_ERA5-Land_hourly_aggregate_stats.json")
    worldpop = read_json("data/exposure_impact/exposure_impact_004_WorldPop_GP_100m_population_sum.json")
    alpha = read_json("data/remote_sensing/remote_sensing_003_Google_Satellite_Embedding_annual_cosine-change_stats.json")
    sentinel1 = read_json("data/remote_sensing/remote_sensing_005_Sentinel-1_GRD_VV_pre_post_change.json")

    hourly_peak = rounded(extract_hourly_peak_mm(wiki.get("extract", "")), 1)
    event_means = {
        "gpm": rounded(gpm["stats"]["gpm_event_precip_mm_mean"]),
        "chirps": rounded(chirps["stats"]["chirps_event_precip_mm_mean"]),
        "era5_land": rounded(era5["stats"]["precipitation_sum_mm_mean"]),
    }
    peak_share = {name: rounded(hourly_peak / value) for name, value in event_means.items()}
    product_spread = rounded(max(event_means.values()) / min(event_means.values()))

    context = overpass_context()
    context.update(
        {
            "population_rounded": int(round(worldpop["population_sum"]["population"] / 1000) * 1000),
            "sentinel1_vv_change_mean_db": rounded(sentinel1["stats"]["s1_vv_post_minus_pre_db_mean"]),
            "alphaearth_change_mean": rounded(alpha["stats"]["alphaearth_1_minus_cosine_mean"]),
        }
    )

    interpretation = (
        "The 201.9 mm Zhengzhou hour is a peak-hour burst inside a wet 2021-07-17 to "
        "2021-07-23 window: all three mean precipitation products exceed 200 mm, and "
        "the hourly peak is 47.4%, 78.7%, and 94.2% of those event-window means."
    )

    return {
        "schema_version": "1.0",
        "task_id": "CSX-051_Q2",
        "event_id": "CSX-051",
        "task_type": "short_answer",
        "target_family": "rainfall_concentration_calibration",
        "evaluation_mode": "hybrid",
        "difficulty_level": "L3",
        "primary_gt": {
            "diagnosis_label": "peak_hour_burst_embedded_in_wet_event_window",
            "hourly_peak_mm": hourly_peak,
            "event_window_mean_mm": event_means,
            "peak_share_of_means": peak_share,
            "product_spread_ratio": product_spread,
            "context_metrics": context,
            "interpretation": interpretation,
        },
        "event": {
            "name": event["event_name"],
            "window": (
                f"{locked['temporal_window']['start_date']} to "
                f"{locked['temporal_window']['end_date']}"
            ),
            "hazard_family": event["hazard_family"],
        },
        "key_values": {
            "hourly_peak_mm": hourly_peak,
            "all_event_means_above_200mm": all(value > 200 for value in event_means.values()),
            "rainfall_product_count": len(event_means),
            "surface_change_metrics": {
                "sentinel1_vv_change_mean_db": context["sentinel1_vv_change_mean_db"],
                "alphaearth_change_mean": context["alphaearth_change_mean"],
            },
        },
        "rubric": {
            "total_points": 20,
            "criteria": scoring_rubric(),
        },
        "provenance": {
            "computed_by": "compute_gt.py",
            "source_files": SOURCE_FILES,
        },
    }


def main() -> None:
    output = build_ground_truth()
    (TASK_DIR / "computed_gt.json").write_text(
        json.dumps(output, indent=2, ensure_ascii=True) + "\n",
        encoding="utf-8",
    )


if __name__ == "__main__":
    main()
